// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 검색 결과 (9번)" (ce7a72e08a46431499f2a428fb4c1b7e).
// #25: GET /api/questions/search에 연결했다. 검색 조건은 모두 URL 쿼리에 두어 페이지 이동·새로고침에도 유지한다.
import { useEffect, useMemo, useState, type KeyboardEvent, type ReactNode } from "react";
import { useSearchParams } from "react-router-dom";
import { getErrorMessage, getFieldErrors } from "../api/client";
import { CATEGORIES, searchQuestions, type Page, type QuestionListItem as Question } from "../api/question";
import Footer from "../components/Footer";
import Header from "../components/Header";
import ListStatus from "../components/ListStatus";
import Pagination from "../components/Pagination";
import QuestionListItem from "../components/QuestionListItem";
import SortTabs from "../components/SortTabs";
import {
  ACCEPTED_OPTIONS,
  MAX_TAGS,
  normalizeTag,
  readCondition,
  SCOPES,
  toApiParams,
  toSearchParams,
  type SearchCondition,
} from "../components/search/searchCondition";
import "./SearchResults.css";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  '/* Subtle dot grid pattern matching the requested neo-brutalist feel */\n    body {\n      background-color: #FFFDF5;\n      background-image: radial-gradient(#d1cfc7 1px, transparent 1px);\n      background-size: 24px 24px;\n      color: #111111;\n      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;\n    }\n  \n\n    .border-neo {\n      border: 2.5px solid #111111;\n    }\n    .border-neo-b {\n      border-bottom: 2.5px solid #111111;\n    }';

type LoadState =
  { status: "loading" } | { status: "error"; message: string } | { status: "done"; data: Page<Question> };

const chipClass = (selected: boolean) =>
  `px-2.5 py-1 text-xs font-bold border-2 border-[#111111] transition-colors ${
    selected ? "bg-[#111111] text-white" : "bg-white hover:bg-[#FFD43B]"
  }`;

function FilterRow({ label, children }: { label: string; children: ReactNode }) {
  return (
    <div className="flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-6 py-2.5">
      <span className="font-bold text-sm text-neutral-900 w-20 flex-shrink-0">{label}</span>
      <div className="flex items-center gap-2 flex-wrap min-w-0">{children}</div>
    </div>
  );
}

export default function SearchResults() {
  const [searchParams, setSearchParams] = useSearchParams();
  const condition = useMemo(() => readCondition(searchParams), [searchParams]);
  const apiParams = useMemo(() => toApiParams(condition), [condition]);
  const requestKey = JSON.stringify(apiParams);
  const [state, setState] = useState<LoadState>({ status: "loading" });
  const [retryKey, setRetryKey] = useState(0);
  const [tagInput, setTagInput] = useState("");
  const [tagWarning, setTagWarning] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState({ status: "loading" });
    searchQuestions(JSON.parse(requestKey))
      .then((data) => {
        if (!cancelled) setState({ status: "done", data });
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        // 400이면 어떤 조건이 틀렸는지 함께 보여준다.
        const reasons = getFieldErrors(error).map((e) => e.reason);
        setState({ status: "error", message: reasons.length > 0 ? reasons.join(" ") : getErrorMessage(error) });
      });
    return () => {
      cancelled = true;
    };
  }, [requestKey, retryKey]);

  // 조건을 바꾸면 1페이지부터 다시 본다. 페이지 이동만 page를 넘긴다.
  function update(next: Partial<SearchCondition>) {
    setSearchParams(toSearchParams({ ...condition, page: 1, ...next }));
    window.scrollTo({ top: 0 });
  }

  function addTag(raw: string) {
    const tag = normalizeTag(raw);
    setTagInput("");
    if (!tag || condition.tags.includes(tag)) return;
    if (condition.tags.length >= MAX_TAGS) {
      setTagWarning(`태그는 최대 ${MAX_TAGS}개까지 고를 수 있습니다.`);
      return;
    }
    setTagWarning("");
    update({ tags: [...condition.tags, tag] });
  }

  function removeTag(tag: string) {
    setTagWarning("");
    update({ tags: condition.tags.filter((t) => t !== tag) });
  }

  function handleTagKeyDown(event: KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Enter" || event.key === ",") {
      event.preventDefault();
      addTag(tagInput);
    } else if (event.key === "Backspace" && !tagInput && condition.tags.length > 0) {
      removeTag(condition.tags[condition.tags.length - 1]);
    }
  }

  // 조건 초기화: 검색어는 두고 나머지 필터를 기본값으로 되돌린다.
  function resetFilters() {
    setTagInput("");
    setTagWarning("");
    update({ categoryId: null, tags: [], startDate: "", endDate: "", accepted: "all", scope: "all" });
  }

  const { keyword, scope } = condition;
  const highlightTitle = keyword && (scope === "all" || scope === "title") ? keyword : undefined;
  const highlightTag = keyword && (scope === "all" || scope === "tag") ? keyword : undefined;
  const hasFilters =
    condition.categoryId !== null ||
    condition.tags.length > 0 ||
    condition.startDate !== "" ||
    condition.endDate !== "" ||
    condition.accepted !== "all" ||
    scope !== "all";
  const data = state.status === "done" ? state.data : null;

  return (
    <div id="page-search-results">
      <style>{css}</style>
      <div
        className="min-h-screen flex flex-col justify-between"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1.2px, transparent 1.2px)",
          backgroundSize: "18px 18px",
        }}
      >
        <Header />

        <main className="max-w-6xl w-full mx-auto px-4 sm:px-6 py-8 flex-1">
          <div className="flex items-baseline gap-2 pb-4 min-w-0">
            <h1 className="text-2xl font-black tracking-tight text-[#111111] break-all">
              {keyword ? `‘${keyword}’ 검색 결과` : "검색 결과"}
            </h1>
            {data && <span className="text-base font-bold text-gray-600">{data.totalElements.toLocaleString()}개</span>}
          </div>

          {/* 검색 조건 (REQ-SEARCH-002~004) */}
          <section
            className="border-neo bg-white shadow-[3px_3px_0_#111111] px-5 py-3 mb-5 divide-y divide-neutral-200"
            aria-label="검색 조건"
          >
            <FilterRow label="검색 범위">
              {SCOPES.map((option) => (
                <label
                  key={option.value}
                  className={`flex items-center gap-1.5 text-sm font-bold mr-3 ${keyword ? "cursor-pointer" : "opacity-40"}`}
                >
                  <input
                    className="w-4 h-4 text-black border-2 border-black focus:ring-0"
                    name="search-results-scope"
                    type="radio"
                    disabled={!keyword}
                    checked={scope === option.value}
                    onChange={() => update({ scope: option.value })}
                  />
                  <span>{option.label}</span>
                </label>
              ))}
              {!keyword && <span className="text-xs text-gray-500">검색어를 입력하면 고를 수 있습니다.</span>}
            </FilterRow>

            <FilterRow label="카테고리">
              <button
                className={chipClass(condition.categoryId === null)}
                type="button"
                aria-pressed={condition.categoryId === null}
                onClick={() => update({ categoryId: null })}
              >
                전체
              </button>
              {CATEGORIES.map((category) => (
                <button
                  key={category.categoryId}
                  className={chipClass(condition.categoryId === category.categoryId)}
                  type="button"
                  aria-pressed={condition.categoryId === category.categoryId}
                  onClick={() => update({ categoryId: category.categoryId })}
                >
                  {category.name}
                </button>
              ))}
            </FilterRow>

            <FilterRow label="태그">
              {condition.tags.map((tag) => (
                <span
                  key={tag}
                  className="inline-flex items-center gap-1 pl-2.5 pr-1 py-0.5 text-xs font-bold bg-[#FFD43B] border-2 border-[#111111]"
                >
                  {tag}
                  <button
                    className="px-1 font-black hover:text-[#E11D48]"
                    type="button"
                    aria-label={`${tag} 태그 해제`}
                    onClick={() => removeTag(tag)}
                  >
                    ✕
                  </button>
                </span>
              ))}
              <input
                className="h-8 w-44 px-2.5 text-xs border-2 border-[#111111] focus:outline-none focus:shadow-[2px_2px_0_#111111]"
                placeholder="태그 입력 후 Enter"
                aria-label="태그 추가"
                maxLength={30}
                value={tagInput}
                onChange={(event) => setTagInput(event.target.value)}
                onKeyDown={handleTagKeyDown}
              />
              {tagWarning && <span className="text-xs font-bold text-[#E11D48]">{tagWarning}</span>}
              {condition.tags.length > 1 && (
                <span className="text-xs text-gray-500">선택한 태그가 모두 달린 질문만 보여줍니다.</span>
              )}
            </FilterRow>

            <FilterRow label="작성일">
              <input
                className="h-8 px-2 text-xs border-2 border-[#111111] focus:outline-none"
                type="date"
                aria-label="시작일"
                max={condition.endDate || undefined}
                value={condition.startDate}
                onChange={(event) => update({ startDate: event.target.value })}
              />
              <span className="text-sm font-bold">~</span>
              <input
                className="h-8 px-2 text-xs border-2 border-[#111111] focus:outline-none"
                type="date"
                aria-label="종료일"
                min={condition.startDate || undefined}
                value={condition.endDate}
                onChange={(event) => update({ endDate: event.target.value })}
              />
            </FilterRow>

            <FilterRow label="채택 여부">
              {ACCEPTED_OPTIONS.map((option) => (
                <button
                  key={option.value}
                  className={chipClass(condition.accepted === option.value)}
                  type="button"
                  aria-pressed={condition.accepted === option.value}
                  onClick={() => update({ accepted: option.value })}
                >
                  {option.label}
                </button>
              ))}
              <button
                className="ml-auto h-8 px-3 text-xs font-bold bg-white border-2 border-[#111111] shadow-[2px_2px_0_#111111] active:translate-x-[2px] active:translate-y-[2px] active:shadow-none disabled:opacity-40 disabled:shadow-none"
                type="button"
                disabled={!hasFilters}
                onClick={resetFilters}
              >
                조건 초기화
              </button>
            </FilterRow>
          </section>

          <div className="flex justify-end pb-3.5">
            <SortTabs value={condition.sort} onChange={(sort) => update({ sort })} />
          </div>

          <section
            aria-label="검색 결과 목록"
            aria-busy={state.status === "loading"}
            className="border-neo bg-white shadow-[3px_3px_0_#111111] divide-y-2 divide-neutral-900"
          >
            {state.status === "loading" && <ListStatus>검색 중입니다...</ListStatus>}
            {state.status === "error" && (
              <ListStatus>
                <p className="text-[#E11D48]">{state.message}</p>
                <button
                  className="mt-4 h-9 px-4 bg-white border-2 border-[#111111] text-sm font-bold shadow-[2px_2px_0_#111111]"
                  type="button"
                  onClick={() => setRetryKey((key) => key + 1)}
                >
                  다시 시도
                </button>
              </ListStatus>
            )}
            {data && data.content.length === 0 && (
              <ListStatus>
                <p className="text-base font-black text-[#111111]">검색 결과가 없습니다.</p>
                <p className="mt-1 text-xs text-gray-500">
                  {condition.page > 1
                    ? "이 페이지에는 결과가 없습니다."
                    : "다른 검색어로 찾아보거나 조건을 줄여보세요."}
                </p>
              </ListStatus>
            )}
            {data?.content.map((question) => (
              <QuestionListItem
                key={question.questionId}
                question={question}
                highlightTitle={highlightTitle}
                highlightTag={highlightTag}
                onTagClick={addTag}
              />
            ))}
          </section>

          <Pagination page={condition.page} totalPages={data?.totalPages ?? 0} onChange={(page) => update({ page })} />
        </main>

        <Footer />
      </div>
    </div>
  );
}
